/* @autogenerated */
import { of, throwError } from 'rxjs';
import { runLocalTask } from './local-task';

describe('runLocalTask', () => {
  it('keeps validation details readable when the connector returns structured errors', (done) => {
    runLocalTask('update', of(['site-1']), () =>
      throwError(() => ({
        status: 422,
        error: [{ field: 'name', code: 'required', description: 'Name is required', rejectedValue: '' }],
      })),
    ).subscribe((task) => {
      const fail = task.steps[0].errors[0]?.fails[0];
      if (fail) {
        expect(fail.code).toBe('422');
        expect(fail.violation).not.toContain('[object Object]');
        expect(fail.wrongValues).toEqual([{ field: 'name', error: 'Name is required', wrong: '' }]);
      }
      if (task.detailStatus === 'FINISHED') done();
    });
  });
});
